34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
42	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    private final TelephoneNormalizer telephoneNormalizer;
69	
70	    private final HouseholdNormalizer householdNormalizer;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper,
76	                                 TelephoneNormalizer telephoneNormalizer,
77	                                 HouseholdNormalizer householdNormalizer) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	        this.telephoneNormalizer = telephoneNormalizer;
83	        this.householdNormalizer = householdNormalizer;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
117	        // A value that cannot form a valid E.164 number is rejected with 400.
118	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
119	        owner.setTelephone(normalizedTelephone);
120	        // Store the (already syntactically validated) email lower-cased so it is persisted and
121	        // returned in canonical form. A missing email is left untouched.
122	        owner.setEmail(normalizeEmail(owner.getEmail()));
123	        // Default the registration date to the server's current date when the client did not
124	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
125	        if (owner.getRegistrationDate() == null) {
126	            owner.setRegistrationDate(java.time.LocalDate.now());
127	        }
128	        // Reject creating an owner whose normalized telephone is already used by another owner.
129	        if (isTelephoneInUse(normalizedTelephone)) {
130	            throw new DuplicateTelephoneException(
131	                "An owner with telephone " + normalizedTelephone + " already exists");
132	        }
133	        // Reject creating an owner who shares a household (same last name and address, compared
134	        // case-insensitively with collapsed whitespace) with an existing owner, unless the request
135	        // explicitly opts in with 'sharesHousehold' true.
136	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
137	            && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
138	            throw new DuplicateHouseholdException(
139	                "An owner with the same last name and address already exists");
140	        }
141	        // Assign the customer code '<LAST3>-<NNNN>' from the last name and a global sequence
142	        // equal to one more than the current number of owners, fixed at creation time.
143	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
144	        this.clinicService.saveOwner(owner);
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        headers.setLocation(UriComponentsBuilder.newInstance()
147	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
148	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
149	    }
150	
151	    /**
152	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
153	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
154	     * syntactically valid address (rejecting anything else with 400).
155	     *
156	     * @param email the email value (may be {@code null})
157	     * @return the lower-cased email, or {@code null} if the input was {@code null}
158	     */
159	    private String normalizeEmail(String email) {
160	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
161	    }
162	
163	    /**
164	     * Builds the customer code '<LAST3>-<NNNN>' for a newly created owner, where LAST3 is the
165	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
166	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
167	     *
168	     * @param lastName the owner's last name
169	     * @return the formatted customer code
170	     */
171	    private String nextCustomerCode(String lastName) {
172	        String prefix = lastName.substring(0, Math.min(3, lastName.length()))
173	            .toUpperCase(java.util.Locale.ROOT);
174	        int sequence = this.clinicService.findAllOwners().size() + 1;
175	        return String.format("%s-%04d", prefix, sequence);
176	    }
177	
178	    /**
179	     * Determines whether the given normalized telephone is already used by an existing owner.
180	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
181	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
182	     * as the same number.
183	     *
184	     * @param normalizedTelephone the normalized (E.164) telephone to look for
185	     * @return {@code true} if another owner already uses this telephone
186	     */
187	    private boolean isTelephoneInUse(String normalizedTelephone) {
188	        if (normalizedTelephone == null) {
189	            return false;
190	        }
191	        return this.clinicService.findAllOwners().stream()
192	            .map(Owner::getTelephone)
193	            .map(telephoneNormalizer::normalize)
194	            .anyMatch(normalizedTelephone::equals);
195	    }
196	
197	    /**
198	     * Determines whether another owner already shares the given household, i.e. has the same last
199	     * name and the same address. The comparison delegates to {@link HouseholdNormalizer} so that
200	     * values differing only in letter case or in incidental whitespace are treated as the same
201	     * household.
202	     *
203	     * @param lastName the last name of the owner being created
204	     * @param address  the address of the owner being created
205	     * @return {@code true} if an existing owner has a matching last name and address
206	     */
207	    private boolean isHouseholdInUse(String lastName, String address) {
208	        String householdKey = householdNormalizer.householdKey(lastName, address);
209	        return this.clinicService.findAllOwners().stream()
210	            .anyMatch(existing -> householdNormalizer
211	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey));
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
217	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
218	        if (currentOwner == null) {
219	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	        }
221	        currentOwner.setAddress(ownerFieldsDto.getAddress());
222	        currentOwner.setCity(ownerFieldsDto.getCity());
223	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
224	        currentOwner.setLastName(ownerFieldsDto.getLastName());
225	        // Normalize the telephone to canonical E.164 form so it is stored and returned
226	        // consistently with create; an unformattable value is rejected with 400.
227	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
228	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
229	        this.clinicService.saveOwner(currentOwner);
230	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Transactional
235	    @Override
236	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
237	        Owner owner = this.clinicService.findOwnerById(ownerId);
238	        if (owner == null) {
239	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	        }
241	        this.clinicService.deleteOwner(owner);
242	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        HttpHeaders headers = new HttpHeaders();
253	        Pet pet = petMapper.toPet(petFieldsDto);
254	        owner.setId(ownerId);
255	        pet.setOwner(owner);
256	        pet.getType().setName(null);
257	        this.clinicService.savePet(pet);
258	        PetDto petDto = petMapper.toPetDto(pet);
259	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
260	            .buildAndExpand(pet.getId()).toUri());
261	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
267	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
268	        if (currentOwner != null) {
269	            Pet currentPet = this.clinicService.findPetById(petId);
270	            if (currentPet != null) {
271	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
272	                currentPet.setName(petFieldsDto.getName());
273	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
274	                this.clinicService.savePet(currentPet);
275	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
276	            }
277	        }
278	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
284	        HttpHeaders headers = new HttpHeaders();
285	        Visit visit = visitMapper.toVisit(visitFieldsDto);
286	        Pet pet = new Pet();
287	        pet.setId(petId);
288	        visit.setPet(pet);
289	        this.clinicService.saveVisit(visit);
290	        VisitDto visitDto = visitMapper.toVisitDto(visit);
291	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
292	            .buildAndExpand(visit.getId()).toUri());
293	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
294	    }
295	
296	
297	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
298	    @Override
299	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
300	        Owner owner = this.clinicService.findOwnerById(ownerId);
301	        if (owner != null) {
302	            Pet pet = owner.getPet(petId);
303	            if (pet != null) {
304	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
305	            }
306	        }
307	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
308	    }
309	}
